import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-remote'),GD('git-clone'),GD('git-fetch'),GD('git-pull'),GD('git-push'),GD('gittutorial-2','Git – gittutorial-2'),('https://docs.gitlab.com/user/ssh/','GitLab Docs – Use SSH keys with GitLab'),('https://www.odoo.com/documentation/20.0/administration/on_premise/source.html','Odoo 20 – Source install')])
def dia(vi):
    t=('Đẩy và lấy commit giữa máy bạn và GitLab' if vi else 'Pushing and fetching commits between your machine and GitLab','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g04'%('vi' if vi else 'en'))
    b=box(10,15,200,110,'Repo trên máy bạn' if vi else 'Repo on your machine','')
    b+='<text class="dg-text" x="26" y="74">main</text><text class="dg-text" x="26" y="96">origin/main %s</text>\n'%('(bản ghi nhớ)' if vi else '(a memory)')
    b+=box(430,15,200,110,'GitLab (origin)','',True)
    b+='<text class="dg-text" x="446" y="74">main</text><text class="dg-text" x="446" y="96">feature/...</text>\n'
    b+='<path class="dg-arrow" d="M214 60 h212 m-8 -6 l8 6 l-8 6" /><text class="dg-text" text-anchor="middle" x="320" y="50">git push</text>\n'
    b+='<path class="dg-arrow" d="M426 100 h-212 m8 -6 l-8 6 l8 6" /><text class="dg-text" text-anchor="middle" x="320" y="90">git fetch</text>\n'
    b+='<text class="dg-text" x="10" y="150">%s</text>\n'%('git pull = git fetch rồi merge origin/main vào nhánh hiện tại.' if vi else 'git pull = git fetch, then merge origin/main into the current branch.')
    return fig('640 165',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a04');base(sb);remote_setup(sb)
    T1=sb.P('git remote add origin git@gitlab.example.com:vinc/vinc_course.git','git remote -v','git push -u origin main','git branch -vv','git status -sb')
    T2=sb.P('cd ..','git clone git@gitlab.example.com:vinc/vinc_course.git vinc_course_binh','cd vinc_course_binh')
    sb.q('git config user.name "Trần Thị Bình"');sb.q('git config user.email "binh.tran@example.com"')
    T3=sb.P('git switch -c feature/course-level',"echo \"    level = fields.Selection([('basic', 'Cơ bản'), ('adv', 'Nâng cao')])\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm trường cấp độ"','git push -u origin feature/course-level')
    T3b=sb.P('cd ../vinc_course','git fetch','git branch -a','git switch feature/course-level','git log --oneline -n 2','git switch main')
    T4=sb.P('cd ../vinc_course_binh','git switch main','echo "# vinc_course" > README.md','git add README.md','git commit -m "[ADD] vinc_course: README"','git push')
    T4b=sb.P('cd ../vinc_course','git fetch','git status -sb','git pull','git log --oneline -n 2')
    T5a=sb.P("echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -am "[IMP] vinc_course: thêm trường học phí"')
    T5b=sb.P('cd ../vinc_course_binh','echo "Module quản lý khóa học." >> README.md','git commit -am "[IMP] vinc_course: mô tả README"','git push')
    T5c=sb.P('cd ../vinc_course','git push')
    T5d=sb.P('git pull')
    T5e=sb.P('git pull --no-rebase','git push','git log --oneline --graph -n 4')
    T6=sb.P('cd ../vinc_course_binh','git push origin --delete feature/course-level','cd ../vinc_course','git fetch --prune','git branch -a')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Remote là bản repo đặt trên máy chủ (thường là GitLab) để cả nhóm cùng đẩy và lấy commit.</strong> Bài này nối repo <code>vinc_course</code> với GitLab: tạo SSH key và đăng ký lên GitLab, <code>clone</code> repo về, <code>push</code> nhánh lên, <code>fetch</code> để xem công việc của đồng nghiệp mà chưa gộp, <code>pull</code> để lấy và gộp, và xử lý lỗi <em>rejected</em> cùng <em>divergent branches</em> mà ai cũng gặp. Để chạy thật, ví dụ dùng một repo bare cục bộ đóng vai GitLab; các lệnh y hệt khi dùng GitLab thật.','<strong>A remote is a copy of the repository on a server (usually GitLab) so the whole team can push and fetch commits.</strong> This part connects the <code>vinc_course</code> repo to GitLab: creating an SSH key and registering it, <code>clone</code>, <code>push</code> a branch, <code>fetch</code> to see colleagues\' work without merging it, <code>pull</code> to fetch and merge, and the <em>rejected</em> and <em>divergent branches</em> errors everyone meets. To run for real, the examples use a local bare repo that plays GitLab; the commands are identical with a real GitLab.')))
    o+=h2('remote-la-gi',t('Remote, origin và nhánh theo dõi','Remotes, origin and tracking branches'))
    o+=p(t('Đến giờ mọi commit chỉ nằm trên máy bạn. Để cộng tác, nhóm đặt một repo trung tâm trên GitLab; mỗi người có repo riêng trên máy và đồng bộ qua repo trung tâm đó. Git gọi repo ở xa là <strong>remote</strong>, và tên mặc định của remote bạn clone về là <code>origin</code>. Một repo có thể có nhiều remote (ví dụ <code>origin</code> của công ty và <code>upstream</code> của dự án gốc).','So far every commit lives only on your machine. To collaborate, the team keeps a central repo on GitLab; each person has their own repo locally and syncs through it. Git calls the faraway repo a <strong>remote</strong>, and the default name of the remote you cloned from is <code>origin</code>. A repo can have several remotes (say the company\'s <code>origin</code> and an <code>upstream</code> of the original project).'))
    o+=dia(vi)
    o+=p(t('Điểm hay gây hiểu nhầm là <code>origin/main</code>: đó <em>không</em> phải nhánh bạn làm việc, mà là <strong>bản ghi nhớ</strong> trên máy bạn về nơi <code>main</code> của GitLab đã đứng ở lần liên lạc gần nhất. Nó chỉ được cập nhật khi bạn <code>fetch</code>, <code>pull</code> hoặc <code>push</code>. Vì vậy “remote đã có commit mới chưa?” là câu hỏi mà Git chỉ trả lời đúng sau khi bạn fetch.','The point that most often confuses people is <code>origin/main</code>: it is <em>not</em> a branch you work on but a <strong>memory</strong> on your machine of where GitLab\'s <code>main</code> stood the last time you talked to it. It only updates when you <code>fetch</code>, <code>pull</code> or <code>push</code>. So “has the remote got new commits?” is a question Git answers correctly only after you fetch.'))
    o+=tbl([t('Lệnh','Command'),t('Tác dụng','What it does')],[
        ['<code>git remote -v</code>',t('Liệt kê remote và URL','List remotes and their URLs')],
        ['<code>git remote add origin &lt;url&gt;</code>',t('Gắn repo cục bộ có sẵn với một remote','Attach an existing local repo to a remote')],
        ['<code>git clone &lt;url&gt;</code>',t('Sao chép repo về máy, tự đặt <code>origin</code>','Copy a repo to your machine and set <code>origin</code> automatically')],
        ['<code>git fetch</code>',t('Tải commit mới về, <em>không</em> sửa nhánh của bạn','Download new commits without touching your branches')],
        ['<code>git pull</code>',t('<code>fetch</code> rồi gộp vào nhánh hiện tại','<code>fetch</code> followed by a merge into where you stand')],
        ['<code>git push</code>',t('Đẩy commit của nhánh hiện tại lên remote','Send your branch\'s commits to the remote')],
        ['<code>git push -u origin &lt;nhánh&gt;</code>',t('Đẩy lần đầu và ghi nhớ nhánh theo dõi','First push, remembering the tracking branch')]])
    o+=h2('ssh',t('Kết nối GitLab bằng SSH key','Connecting to GitLab with an SSH key'))
    o+=p(t('Có hai cách xác thực khi clone: HTTPS (hỏi tài khoản) hoặc SSH. Theo tài liệu GitLab, SSH dùng một cặp khóa gồm <strong>khóa công khai</strong> (đưa cho GitLab) và <strong>khóa riêng</strong> (giữ kín trên máy bạn), nhờ đó bạn không phải nhập tên đăng nhập và mật khẩu mỗi lần push hay pull. Một khóa dùng được cho mọi dự án mà tài khoản có quyền, bạn không cần khóa riêng cho từng dự án. Loại khóa được ưu tiên là <strong>ED25519</strong>. Làm một lần trên mỗi máy:','There are two ways to authenticate when cloning: HTTPS (asks for credentials) or SSH. According to GitLab\'s documentation, SSH uses a key pair made of a <strong>public key</strong> (given to GitLab) and a <strong>private key</strong> (kept secret on your machine), so you do not enter a username and password on every push or pull. One key works for every project your account can reach; you do not need one per project. The preferred key type is <strong>ED25519</strong>. Do this once per machine:'))
    o+=pre(t('# 1. Tạo cặp khóa (comment là email để nhận diện khóa)\nssh-keygen -t ed25519 -C "an.nguyen@example.com"\n# Nhấn Enter để nhận tên file mặc định ~/.ssh/id_ed25519, nên đặt passphrase\n\n# 2. Nạp khóa riêng vào ssh-agent\nssh-add ~/.ssh/id_ed25519\n\n# 3. In khóa CÔNG KHAI để copy (file .pub, không phải file không đuôi)\ncat ~/.ssh/id_ed25519.pub\n\n# 4. Sau khi dán khóa vào GitLab, kiểm tra kết nối\nssh -T git@gitlab.example.com\n# Welcome to GitLab, @tên-bạn!','# 1. Create the key pair (the comment is your email, to identify the key)\nssh-keygen -t ed25519 -C "an.nguyen@example.com"\n# Press Enter to accept the default file ~/.ssh/id_ed25519, and set a passphrase\n\n# 2. Load the private key into ssh-agent\nssh-add ~/.ssh/id_ed25519\n\n# 3. Print the PUBLIC key to copy (the .pub file, not the extensionless one)\ncat ~/.ssh/id_ed25519.pub\n\n# 4. After pasting the key into GitLab, test the connection\nssh -T git@gitlab.example.com\n# Welcome to GitLab, @your-name!'))
    o+=ul([t('Trong GitLab: bấm avatar → <em>Edit profile</em> → <em>Access</em> → <em>SSH keys</em> → <em>Add new key</em>, dán khóa công khai, đặt tiêu đề như “Laptop công ty” rồi <em>Add key</em>.','In GitLab: click your avatar → <em>Edit profile</em> → <em>Access</em> → <em>SSH keys</em> → <em>Add new key</em>, paste the public key, give it a title such as “Work laptop” and click <em>Add key</em>.'),t('Thay <code>gitlab.example.com</code> bằng địa chỉ GitLab của công ty (với GitLab.com là <code>gitlab.com</code>). Lần kết nối đầu ssh hỏi xác nhận máy chủ; hãy đối chiếu dấu vân tay với trang tài liệu của GitLab trước khi gõ <code>yes</code>.','Replace <code>gitlab.example.com</code> with your company\'s GitLab address (<code>gitlab.com</code> for GitLab.com). On first connection ssh asks you to confirm the server; compare its fingerprint with GitLab\'s documentation before typing <code>yes</code>.'),t('<strong>Không bao giờ dán hay gửi khóa riêng</strong> (file <code>id_ed25519</code>). Chỉ file <code>.pub</code> mới được chia sẻ.','<strong>Never paste or send the private key</strong> (the <code>id_ed25519</code> file). Only the <code>.pub</code> file may be shared.')])
    o+=tbl([t('Kiểu','Type'),t('URL ví dụ','Example URL'),t('Xác thực','Authentication')],[
        ['SSH','<code>git@gitlab.example.com:vinc/vinc_course.git</code>',t('Cặp khóa SSH, không hỏi mật khẩu mỗi lần','An SSH key pair, no password prompt each time')],
        ['HTTPS','<code>https://gitlab.example.com/vinc/vinc_course.git</code>',t('Hỏi thông tin đăng nhập khi kết nối','Asks for credentials when connecting')]])
    o+=p(t('Cả hai URL trỏ cùng một repo; khác nhau chỉ ở cách chứng minh bạn là ai. Đã clone bằng URL nào mà muốn đổi, dùng <code>git remote set-url origin &lt;url-mới&gt;</code>. Trang dự án trên GitLab có sẵn nút <em>Code</em> để sao chép cả hai dạng URL.','Both URLs point to the same repo; they differ only in how you prove who you are. If you cloned with one and want the other, use <code>git remote set-url origin &lt;new-url&gt;</code>. The project page on GitLab has a <em>Code</em> button to copy either form.'))
    o+=h2('clone-push',t('Nối repo với GitLab: push lần đầu và clone','Connecting a repo to GitLab: first push and clone'))
    o+=p(t('Nếu repo đã có sẵn trên máy (như <code>vinc_course</code> của chúng ta), hãy tạo một dự án trống trên GitLab, thêm remote rồi đẩy lên. Cờ <code>-u</code> (<code>--set-upstream</code>) ghi nhớ rằng <code>main</code> theo dõi <code>origin/main</code>, nhờ đó từ nay chỉ cần gõ <code>git push</code> và <code>git pull</code> trơn.','If the repo already exists on your machine (like our <code>vinc_course</code>), create an empty project on GitLab, add the remote and push. The <code>-u</code> flag (<code>--set-upstream</code>) remembers that <code>main</code> tracks <code>origin/main</code>, so from now on a plain <code>git push</code> and <code>git pull</code> are enough.'))
    o+=T1
    o+=p(t('<code>git status -sb</code> giờ in <code>## main...origin/main</code>: nhánh của bạn và bản ghi nhớ đang khớp nhau. Đồng nghiệp là Bình, ở máy khác, lấy repo về bằng <code>git clone</code>; lệnh này tạo thư mục, trỏ <code>origin</code> và checkout nhánh mặc định:','<code>git status -sb</code> now prints <code>## main...origin/main</code>: your branch and its memory match. Your colleague Binh, on another machine, gets the repo with <code>git clone</code>, which creates the folder, points <code>origin</code> and checks out the default branch:'))
    o+=T2
    o+=h2('push-fetch',t('Làm việc song song: push nhánh, fetch để xem','Working in parallel: pushing a branch and fetching to look'))
    o+=p(t('Bình tạo nhánh cấp độ, commit và đẩy lên GitLab. Đây là nhánh mới nên remote chưa biết, và cờ <code>-u</code> lại hữu ích:','Binh creates the level branch, commits and pushes it to GitLab. It is a new branch so the remote does not know it yet, and <code>-u</code> comes in handy again:'))
    o+=T3
    o+=p(t('Trên máy An chưa có gì thay đổi cho tới khi An <code>fetch</code>. Sau fetch, nhánh của Bình xuất hiện dưới dạng <code>origin/feature/course-level</code> để An xem hoặc review mà chưa đụng vào nhánh nào của mình. Chuyển sang tên nhánh đó, Git tự tạo nhánh cục bộ cùng tên và nối theo dõi:','Nothing changes on An\'s machine until An runs <code>fetch</code>. After the fetch, Binh\'s branch appears as <code>origin/feature/course-level</code> for An to inspect or review without touching any of An\'s own branches. Switching to that name makes Git create a local branch called the same and wire up tracking:'))
    o+=T3b
    o+=h2('pull',t('fetch và pull: khác nhau ở chỗ nào','fetch and pull: where they differ'))
    o+=p(t('<code>git pull</code> thực chất là <code>git fetch</code> cộng thêm <code>git merge</code> vào nhánh hiện tại. Thói quen an toàn là <strong>fetch trước, xem rồi mới gộp</strong>: bạn thấy được commit nào sắp về. Ví dụ Bình đẩy một commit README lên <code>main</code>; An fetch, thấy mình đang <em>behind 1</em>, rồi pull và Git chỉ việc fast-forward:','<code>git pull</code> is in effect <code>git fetch</code> plus a <code>git merge</code> into the branch you are on. A safe habit is <strong>fetch first, look, then merge</strong>, so you see which commits are coming. For example Binh pushes a README commit to <code>main</code>; An fetches, sees <em>behind 1</em>, then pulls and Git simply fast-forwards:'))
    o+=T4+T4b
    o+=h2('bi-tu-choi',t('Khi push bị từ chối và pull báo “divergent”','When a push is rejected and pull says “divergent”'))
    o+=p(t('Tình huống kinh điển trong nhóm: An commit trên máy mình, trong lúc đó Bình đã đẩy commit khác lên cùng nhánh. Lịch sử của hai người đã rẽ, nên GitLab không cho An đẩy đè lên. Hãy tái hiện:','The classic team situation: An commits locally while Binh pushes another commit to the same branch. Their histories have split, so GitLab does not let An push over it. Let us reproduce it:'))
    o+=T5a+T5b+T5c
    o+=p(t('Thông báo <em>rejected … (fetch first)</em> nghĩa là remote có commit mà máy bạn chưa có. Hãy lấy chúng về trước. Nhưng lần này <code>git pull</code> không chịu chạy vì Git không biết nên gộp bằng merge hay rebase:','The <em>rejected … (fetch first)</em> message means the remote holds commits your machine does not have. Fetch them first. But this time <code>git pull</code> refuses to run because Git does not know whether to reconcile with merge or rebase:'))
    o+=T5d
    o+=p(t('Git liệt kê ba lựa chọn cấu hình. Tạm thời hãy chọn merge bằng cờ <code>--no-rebase</code>; bài 8 sẽ so sánh với rebase. Vì hai commit sửa file khác nhau nên Git tự gộp được, rồi bạn đẩy lên:','Git lists three configuration choices. For now pick merge with the <code>--no-rebase</code> flag; part 8 compares it with rebase. Because the two commits touch different files, Git merges them on its own and then you push:'))
    o+=T5e
    o+=p(t('Để khỏi bị hỏi mỗi lần, bạn có thể đặt mặc định: <code>git config --global pull.rebase false</code> (merge), <code>pull.rebase true</code> (rebase) hoặc <code>pull.ff only</code> (chỉ chấp nhận fast-forward, thận trọng nhất). Hãy thống nhất với nhóm.','To avoid the question every time you can set a default: <code>git config --global pull.rebase false</code> (merge), <code>pull.rebase true</code> (rebase) or <code>pull.ff only</code> (accept fast-forward only, the most cautious). Agree on one with your team.'))
    o+=h2('don-nhanh',t('Dọn nhánh remote','Cleaning up remote branches'))
    o+=p(t('Sau khi nhánh được merge, xóa luôn cả bản trên GitLab. <code>git push origin --delete &lt;nhánh&gt;</code> xóa nhánh trên remote; máy của đồng nghiệp vẫn còn bản ghi nhớ cũ nên họ chạy <code>git fetch --prune</code> để dọn. Nhánh cục bộ cùng tên vẫn còn và phải xóa riêng bằng <code>git branch -d</code>.','Once a branch is merged, delete the copy on GitLab as well. <code>git push origin --delete &lt;branch&gt;</code> removes the remote branch; colleagues still hold the old memory of it, so they run <code>git fetch --prune</code> to tidy up. A local copy with that name remains and must be deleted separately with <code>git branch -d</code>.'))
    o+=T6
    o+=h2('trong-odoo',t('Remote trong công việc Odoo','Remotes in Odoo work'))
    o+=tbl([t('Tình huống','Situation'),t('Cách làm','What to do')],[
        [t('Lấy mã nguồn Odoo','Getting the Odoo source'),t('<code>git clone --branch 20.0 --single-branch https://github.com/odoo/odoo.git</code>: chỉ lấy nhánh 20.0 cho nhẹ','<code>git clone --branch 20.0 --single-branch https://github.com/odoo/odoo.git</code>: only branch 20.0, to keep it light')],
        [t('Module riêng của công ty','The company\'s own module'),t('Một repo GitLab cho <code>vinc_course</code>, cả nhóm clone và đẩy nhánh tính năng','One GitLab repo for <code>vinc_course</code>; everyone clones and pushes feature branches')],
        [t('Cập nhật server thử nghiệm','Updating a staging server'),t('Nhiều nhóm <code>git fetch</code> rồi chuyển sang đúng nhánh hoặc tag cần triển khai thay vì chép file','Many teams <code>git fetch</code> then switch to the exact branch or tag to deploy instead of copying files')],
        [t('Hai remote','Two remotes'),t('<code>git remote add upstream &lt;url&gt;</code> để theo dõi dự án gốc song song với <code>origin</code>','<code>git remote add upstream &lt;url&gt;</code> to follow the original project next to <code>origin</code>')]])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Push bị <em>rejected</em>.</strong> Đừng vội ép. Hãy <code>git pull</code> (hoặc <code>fetch</code> rồi xem), xử lý rồi push lại như ở trên.','<strong>A push is <em>rejected</em>.</strong> Do not rush to force it. Run <code>git pull</code> (or <code>fetch</code> and look), resolve, then push again as above.'),
        t('<strong>Dùng <code>git push --force</code> cho nhanh.</strong> Ép đẩy sẽ ghi đè commit của đồng nghiệp trên remote. Nếu thật sự phải ép (ví dụ sau khi rebase nhánh riêng), hãy dùng <code>--force-with-lease</code>: nó từ chối khi remote có commit mà bạn chưa thấy. Không bao giờ ép lên nhánh chung như <code>main</code>.','<strong>Using <code>git push --force</code> to get it over with.</strong> A forced push overwrites colleagues\' commits on the remote. If you truly must (say after rebasing your own branch) use <code>--force-with-lease</code>: it refuses when the remote holds commits you have not seen. Never force onto a shared branch such as <code>main</code>.'),
        t('<strong>Dán nhầm khóa riêng lên GitLab.</strong> Chỉ dán nội dung file <code>.pub</code> (bắt đầu bằng <code>ssh-ed25519</code>). Nếu lỡ lộ khóa riêng, hãy tạo cặp khóa mới và xóa khóa cũ khỏi GitLab.','<strong>Pasting the private key into GitLab.</strong> Paste only the contents of the <code>.pub</code> file (it starts with <code>ssh-ed25519</code>). If a private key leaks, generate a new pair and delete the old key from GitLab.'),
        t('<strong>Tưởng <code>origin/main</code> luôn mới nhất.</strong> Nó chỉ mới tới lần <code>fetch</code> gần nhất; hãy fetch trước khi so sánh hay quyết định gộp.','<strong>Assuming <code>origin/main</code> is always current.</strong> It is only as fresh as your last <code>fetch</code>; fetch before comparing or deciding to merge.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Remote (<code>origin</code>) là repo trung tâm; <code>origin/main</code> là bản ghi nhớ trên máy bạn, chỉ mới sau <code>fetch</code>.','The remote (<code>origin</code>) is the central repo; <code>origin/main</code> is a memory on your machine, fresh only after <code>fetch</code>.'),t('SSH key ED25519: khóa công khai cho GitLab, khóa riêng ở lại máy bạn.','ED25519 SSH key: the public key goes to GitLab, the private key stays on your machine.'),t('<code>clone</code> lấy repo về; <code>push -u</code> đẩy nhánh lần đầu; <code>fetch</code> xem trước; <code>pull</code> = fetch + merge.','<code>clone</code> gets the repo; <code>push -u</code> sends a branch the first time; <code>fetch</code> looks first; <code>pull</code> = fetch + merge.'),t('<em>Rejected</em> và <em>divergent</em> nghĩa là lịch sử đã rẽ: lấy commit về, gộp, rồi đẩy; tránh <code>--force</code>.','<em>Rejected</em> and <em>divergent</em> mean history has split: fetch, integrate, then push; avoid <code>--force</code>.')])
    o+=p(t('Giờ bạn đã có nhánh trên GitLab. Nhưng trong doanh nghiệp, hiếm khi ai merge thẳng bằng lệnh: họ mở một <strong>merge request</strong> để đồng nghiệp xem code trước khi vào nhánh chính. Đó là chủ đề của bài 5.','You now have branches on GitLab. But in a company hardly anyone merges directly with a command: they open a <strong>merge request</strong> so colleagues review the code before it reaches the main branch. That is the subject of part 5.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
